create or replace function public.bank_fee_active_subsidiary()returns bigint language sql stable security definer set search_path=public as $$select coalesce(active_subsidiary_id(),(select us.subsidiary_id from user_subsidiaries us where us.user_id=app_user_id()order by us.subsidiary_id limit 1))$$;
create or replace function public.bank_fee_options()returns jsonb language sql stable security definer set search_path=public as $$select jsonb_build_object('subsidiary',jsonb_build_object('id',s.subsidiary_id,'name',s.name),'expenseAccount',(select jsonb_build_object('id',ca.account_id,'number',ca.account_number,'name',ca.account_name)from chart_accounts ca where ca.account_id=bank_fee_expense_account(s.subsidiary_id)),'accounts',coalesce((select jsonb_agg(jsonb_build_object('id',ba.bank_account_id,'bankId',b.bank_id,'bankName',b.bank_name,'number',ba.account_number,'currencyId',ba.currency_id,'currencyCode',c.currency_code,'ledgerNumber',ca.account_number,'ledgerName',ca.account_name)order by b.bank_name,ba.account_number)from bank_account ba join banks b using(bank_id)join currencies c using(currency_id)join chart_accounts ca on ca.account_id=ba.account_id where ba.subsidiary_id=s.subsidiary_id and not coalesce(ba.is_credit_card,false)),'[]'::jsonb),'periods',coalesce((select jsonb_agg(jsonb_build_object('id',fp.fiscal_period_id,'name',fp.period_name,'start',fp.start_date,'end',fp.end_date))from fiscal_periods fp where fp.subsidiary_id=s.subsidiary_id and not fp.is_closed),'[]'::jsonb))from subsidiaries s where s.subsidiary_id=bank_fee_active_subsidiary()$$;
grant execute on function public.bank_fee_active_subsidiary(),public.bank_fee_options()to authenticated;
notify pgrst,'reload schema';
